    private Task ValidateCityAsync(ValidatorEventArgs e, CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();

        try
        {
            int? value = Convert.ToInt32(e.Value);
            value = (value > 0 ? value : null);

            RequiredAttribute? requiredAttr = AttributesHelper.GetRequiredAttribute<LaboratoryDto>(x => x.CityId);
            requiredAttr?.Validate(value, new ValidationContext(model));

            e.Status = ValidationStatus.Success;
            e.ErrorText = "";
        }
        catch(ValidationException ex)
        {
            e.Status = ValidationStatus.Error;
            e.ErrorText = ex.ValidationResult.ErrorMessage;
        }
        catch(Exception ex)
        {
            ErrorState.SetError(ex);
        }

        return Task.CompletedTask;
    }

    private async Task SubmitAsync()
    {
        try
        {
            bool isValidate = await validationsRef.ValidateAll().ConfigureAwait(false);
            if(!isValidate)
            {
                return;
            }

            await validationsRef.ClearAll().ConfigureAwait(false);

            // ***************************************************

            await loadingRef.Show().ConfigureAwait(false);

            if(OnSubmit != null)
            {
                await OnSubmit.Invoke().ConfigureAwait(false);
            }
        }
        catch(Exception ex)
        {
            ErrorState.SetError(ex);
        }
        finally
        {
            await loadingRef.Hide().ConfigureAwait(false);
        }
    }

